Certainly! Below is a complex smart contract written in Solidity, designed to function as a decentralized voting system. This contract includes features such as candidate registration, voting, and result tallying, while ensuring security and transparency.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract DecentralizedVoting {
    struct Candidate {
        string name;
        uint voteCount;
    }

    struct Voter {
        bool voted;
        uint vote;
    }

    address public owner;
    mapping(address => Voter) public voters;
    Candidate[] public candidates;
    uint public totalVotes;

    event CandidateRegistered(string name);
    event VoteCasted(address voter, uint candidateIndex);
    event VotingEnded(string winner);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only the owner can perform this action.");
        _;
    }

    modifier onlyVoter() {
        require(voters[msg.sender].voted == false, "You have already voted.");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function registerCandidate(string memory name) public onlyOwner {
        candidates.push(Candidate(name, 0));
        emit CandidateRegistered(name);
    }

    function vote(uint candidateIndex) public onlyVoter {
        require(candidateIndex < candidates.length, "Invalid candidate index.");
        voters[msg.sender].voted = true;
        voters[msg.sender].vote = candidateIndex;
        candidates[candidateIndex].voteCount += 1;
        totalVotes += 1;
        emit VoteCasted(msg.sender, candidateIndex);
    }

    function endVoting() public onlyOwner {
        string memory winnerName = candidates[0].name;
        uint winnerVoteCount = candidates[0].voteCount;

        for (uint i = 1; i < candidates.length; i++) {
            if (candidates[i].voteCount > winnerVoteCount) {
                winnerName = candidates[i].name;
                winnerVoteCount = candidates[i].voteCount;
            }
        }

        emit VotingEnded(winnerName);
    }

    function getTotalVotes() public view returns (uint) {
        return totalVotes;
    }

    function getCandidate(uint index) public view returns (string memory, uint) {
        require(index < candidates.length, "Invalid candidate index.");
        return (candidates[index].name, candidates[index].voteCount);
    }
}
```

This smart contract includes the following features:
- Candidate registration by the owner.
- Voting by registered voters.
- Tallying of votes and declaration of the winner.
- Events to log significant actions.

The contract ensures that only the owner can register candidates and end the voting process, while voters can only vote once. The contract also includes functions to retrieve the total number of votes and the details of each candidate.

